function jpop(g: number) : string {
    let s : string = ""
    for (let i : number = 0; i < 12; i++) {
        if (i % 4 == 1) {
            s = s + "K"
        } else if (i % 4 == 2) {
            s = s + "E"
        } else if (i % 4 == 0) {
            s = s + "S"
        } else {
            s = s + g + "."
        }
    }
    return s
}

